commands.run:
$raw = & "$env:MANGOSTUDIO_BIN_DIR\mangostudio.cmd" upgrade --check --json
if ($LASTEXITCODE -ne 0) {
  Write-Error "upgrade --check exited $LASTEXITCODE"
  exit 1
}
Write-Host ($raw -join "`n")
$report = ($raw -join "`n") | ConvertFrom-Json
if ($report.installedVia.manager -ne 'self-managed') {
  Write-Error "Expected installedVia.manager self-managed, got $($report.installedVia.manager)"
  exit 1
}

# install.ps1 fails via `throw`, which — with $ErrorActionPreference
# = 'Stop' inside it — aborts this whole run block on its own;
# $LASTEXITCODE only ever reflects native .exe calls, never a
# PowerShell script invocation, so it is not a signal to check here.
& scripts\install\install.ps1 -Use $env:DRY_RUN_VERSION

New-Item -ItemType Directory -Force "$env:MANGOSTUDIO_INSTALL_DIR\0.0.0-old" | Out-Null
& scripts\install\install.ps1 -Prune
if (Test-Path "$env:MANGOSTUDIO_INSTALL_DIR\0.0.0-old") {
  Write-Error "-Prune left a stale version directory behind"
  exit 1
}
if (-not (Test-Path "$env:MANGOSTUDIO_INSTALL_DIR\$env:DRY_RUN_VERSION")) {
  Write-Error "-Prune removed the current version"
  exit 1
}

& scripts\install\install.ps1 -Uninstall
if (Test-Path $env:MANGOSTUDIO_INSTALL_DIR) {
  Write-Error "-Uninstall left the install root behind"
  exit 1
}
